Steps:
[AUTH role=LOYALTY_VIP_USER]
[GQL-OP setup_me_vip]
  query { me { id } }
[GQL-EXEC setup_me_vip]
[GQL-CAPTURE setup_me_vip.data.me.id → VIP_USER_ID]
[GQL-OP cleanup_pre_vip]
  mutation { clearCart(command: { storeId: "{{STORE_ID}}" userId: "{{VIP_USER_ID}}" cartName: "default" }) { id } }
[GQL-EXEC cleanup_pre_vip]
[GQL-OP find_wh001_vip]
  query($storeId: String!, $userId: String!, $filter: String!) {
    products(storeId: $storeId userId: $userId currencyCode: "USD" cultureName: "en-US" filter: $filter first: 1) {
      items { id code }
    }
  }
[GQL-VARS find_wh001_vip] {"storeId": "{{STORE_ID}}", "userId": "{{VIP_USER_ID}}", "filter": "code:WH-001 category.subtree:@td(VIRTUAL_CATALOG_B2B.id)"}
[GQL-EXEC find_wh001_vip]
[GQL-CAPTURE find_wh001_vip.data.products.items.0.id → WH001_PROD_ID]
[GQL-OP add_wh001_vip]
  mutation { addItem(command: { cartName: "default" storeId: "{{STORE_ID}}" userId: "{{VIP_USER_ID}}" productId: "{{WH001_PROD_ID}}" quantity: 1 }) { id } }
[GQL-EXEC add_wh001_vip]
[GQL-OP read_cart_vip]
  query {
    cart(cartName: "default" storeId: "{{STORE_ID}}" userId: "{{VIP_USER_ID}}" currencyCode: "USD" cultureName: "en-US") {
      items { sku loyaltyPoints { amount currency { code } } }
      loyaltyPoints { amount currency { code } }
    }
  }
[GQL-EXEC read_cart_vip]
[GQL-CAPTURE read_cart_vip.data.cart.items[?sku=WH-001].loyaltyPoints.amount → VIP_WH001_AMT]
[GQL-OP cleanup_post_vip]
  mutation { clearCart(command: { storeId: "{{STORE_ID}}" userId: "{{VIP_USER_ID}}" cartName: "default" }) { id } }
[GQL-EXEC cleanup_post_vip]

